import{_ as a,o as t,c as s,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const d="/bilder/schueler/individualdaten-ii-migrationshintergrund.png",l="/bilder/schueler/individualdaten-ii-zusaetzliche-felder.png",u="/bilder/schueler/individualdaten-ii-deutschfoerderung.png",h="/bilder/schueler/individualdaten-ii-aktuelle-foerderung.png",o="/bilder/schueler/individualdaten-ii-besondere-merkmale.png",w=JSON.parse('{"title":"Einwanderungsgeschichte und Förderung in Individualdaten II erfassen","description":"","frontmatter":{"title":"Einwanderungsgeschichte und Förderung in Individualdaten II erfassen","source_pageid":379,"source_revision":7201},"headers":[],"relativePath":"schild3/schueler/individualdaten-ii-schueler.md","filePath":"schild3/schueler/individualdaten-ii-schueler.md"}'),g={name:"schild3/schueler/individualdaten-ii-schueler.md"};function c(m,i,f,p,k,b){return t(),s("div",null,[...i[0]||(i[0]=[r('<h1 id="einwanderungsgeschichte-und-forderung-in-individualdaten-ii-erfassen" tabindex="-1">Einwanderungsgeschichte und Förderung in Individualdaten II erfassen <a class="header-anchor" href="#einwanderungsgeschichte-und-forderung-in-individualdaten-ii-erfassen" aria-label="Permalink to &quot;Einwanderungsgeschichte und Förderung in Individualdaten II erfassen&quot;">​</a></h1><p>Erfassen Sie Einwanderungsgeschichte, Förderangaben und besondere Merkmale. Je nach Schulform stehen weitere Felder zum bisherigen Schulbesuch zur Verfügung.</p><p>In den <em>Individualdaten II</em> werden Informationen zur Einwanderungsgeschichte, dem Schulbesuch und sonderpädagogischen Förderungen eines Schülers erfasst.</p><h2 id="migrationshintergrund" tabindex="-1">Migrationshintergrund <a class="header-anchor" href="#migrationshintergrund" aria-label="Permalink to &quot;Migrationshintergrund&quot;">​</a></h2><p><a href="/bilder/schueler/individualdaten-ii-migrationshintergrund.png"><img src="'+d+'" alt="Wurde der Haken Migrationshintergrund vorhanden gesetzt, können hier Details erfasst werden." loading="lazy"></a></p><p><em>Wurde der Haken <strong>Migrationshintergrund vorhanden</strong> gesetzt, können hier Details erfasst werden.</em></p><p>Wurde der Haken gesetzt, dass ein <strong>Migrationshintergrund vorhanden</strong> ist, können die Daten hier nun erfasst werden.</p><p>Beachten Sie die statistikrelevanten Felder, die durch den &quot;<strong>*</strong>&quot; kenntlich gemacht werden.</p><p>Weiterhin können Daten zu <em>Erst-</em> und <em>Anschlussförderung</em> aufgenommen werden.</p><p>Nehmen Sie an dieser Stelle das Tutorial zur <a href="/schild3/schueler/eingabe-von-fluechtlingskindern-tutorial.html">Geflüchtete Kinder und Jugendliche erfassen</a> zur Kenntnis.</p><h2 id="weitere-felder-nach-schulform" tabindex="-1">Weitere Felder nach Schulform <a class="header-anchor" href="#weitere-felder-nach-schulform" aria-label="Permalink to &quot;Weitere Felder nach Schulform&quot;">​</a></h2><p><a href="/bilder/schueler/individualdaten-ii-zusaetzliche-felder.png"><img src="'+l+'" alt="Weitere Felder, die basierend auf der Schulform eigeblendet werden können." loading="lazy"></a></p><p><em>Weitere Felder, die basierend auf der Schulform eigeblendet werden können.</em></p><p>Abhängig von der Schulform können weitere Abschnitte eingeblendet werden.</p>',14),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("An einer weiterführenden Schule wird ein Feld für Daten zum "),e("em",null,"Grundschulbesuch"),n(" erscheinen, während bei Schulen mit einer gymnasialen Oberstufe auch die Erfassung des "),e("em",null,"Sekundarstufe I"),n("-Besuchs ermöglicht wird.")]),e("p",null,[n("An Berufskollegs wird hier die statistikrelevante "),e("em",null,"Anrechnungsmonate nach der Berufskollegsanrechnungs-​ und -​zulassungsverordnung (BKAZVO)"),n(" vorgenommen.")])],-1),r('<p>Beim <em>Grundschulbesuch</em> ist die tatsächliche Dauer der Schuleingangsphase zu erfassen. <strong>01 und 02 sind Jahrgänge; E1, E2 und E3 bezeichnen die darin verbrachten Schuljahre.</strong> Übernehmen Sie den abschließenden EP-Wert aus den Unterlagen der Grundschule. Er lässt sich nicht allein aus der zuletzt besuchten Klasse ableiten. Die laufende Zuordnung und die Korrekturmöglichkeit ab Jahrgang 03 erläutert <a href="/schild3/schueler/eintragung-der-ep-jahre-tutorial.html">Die Jahre der Schuleingangsphase eintragen</a>.</p><p>Diese Angabe ist für die Berechnung der Vollzeitschulpflicht relevant: Nach <a href="https://bass.schule.nrw/6043.htm" target="_blank" rel="noreferrer">§ 37 Absatz 1 SchulG</a> zählt das dritte Jahr der Schuleingangsphase nicht auf deren Dauer. Eine Wiederholung in Klasse 3 oder 4 ist damit nicht gleichzusetzen.</p><p>Ebenso erscheinen hier an <em>Berufskollegs</em> ein Bereich für das <strong>Einschulungsjahr</strong>, die <strong>BKAZVO-Anrechungszeit (Monate)</strong> und die <strong>Berufsqualifikation</strong> auf.</p><h2 id="aktuelle-forderung-und-deutschforderung" tabindex="-1">Aktuelle Förderung und Deutschförderung <a class="header-anchor" href="#aktuelle-forderung-und-deutschforderung" aria-label="Permalink to &quot;Aktuelle Förderung und Deutschförderung&quot;">​</a></h2><p><a href="/bilder/schueler/individualdaten-ii-deutschfoerderung.png"><img src="'+u+'" alt="Erfassen einer eventuellen Deutschförderung." loading="lazy"></a></p><p><em>Erfassen einer eventuellen Deutschförderung.</em></p><p>Erfassen Sie unter <strong>Deutschförderung</strong> Beginn und Ende der Förderung sowie die Angabe zum <strong>Lernstandsbericht</strong>.</p><p><a href="/bilder/schueler/individualdaten-ii-aktuelle-foerderung.png"><img src="'+h+'" alt="Erfassen der aktuellen Förderung." loading="lazy"></a></p><p><em>Erfassen der aktuellen Förderung.</em></p><p>Unter <strong>Aktuelle Förderung</strong> werden die Angaben zum ausgewählten Lernabschnitt angezeigt. Ändern Sie diese unter <strong>Schüler ➜ Akt. Halbjahr ➜ Allgemeine Angaben</strong>, wie im <a href="/schild3/unterricht-kataloge/foerderschwerpunkte-allgemeine-kataloge.html">Katalogartikel zu Förderschwerpunkten</a> beschrieben:</p><ul><li><strong>Hauptförderschwerpunkt</strong></li><li><strong>Weiterer Förderschwerpunkt</strong></li></ul><p>Dazu gehören die Kennzeichen <strong>AO-SF</strong>, <strong>Zieldifferentes Lernen</strong>, <strong>Schwerstbehinderung</strong> und <strong>Autismus</strong>. Die Erfassung der <em>Schwerstbehinderung</em> ist statistikrelevant.</p>',12),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Beachten Sie bei der Erfassung der "),e("em",null,"Förderschwerpunkte"),n(" die aktuellen "),e("strong",null,"Schlüsseltabellen zur Statistik"),n(". Aus den (zulässigen bzw. unzulässigen) Kombinationen geht bei der Auswertung auch hervor, ob zieldifferentes oder zielgleiches Lernen erfolgt.")])],-1),r('<h2 id="besondere-merkmale" tabindex="-1">Besondere Merkmale <a class="header-anchor" href="#besondere-merkmale" aria-label="Permalink to &quot;Besondere Merkmale&quot;">​</a></h2><p><a href="/bilder/schueler/individualdaten-ii-besondere-merkmale.png"><img src="'+o+'" alt="Erfassung möglicher besonderer Merkmale." loading="lazy"></a></p><p><em>Erfassung möglicher besonderer Merkmale.</em></p><p>Hier können auf individueller Basis Merkmale zugeordnet werden. Es können nur Merkmale gewählt werden, die unter <em>Verwaltung</em> für die <em>Schule</em> unter <em>Weitere Angaben</em> als Merkmal eingestellt wurden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Individualdaten_II_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7201.</p>',6)])])}const v=a(g,[["render",c]]);export{w as __pageData,v as default};
